WITH base AS (SELECT *, UPPER(location) AS location_upper, COALESCE(location, 'NONE') AS location_filled FROM departments WHERE location IS NOT NULL AND dept_name <> 'Finance') SELECT CASE WHEN budget >= 3588000 THEN 'HIGH' ELSE 'LOW' END AS budget_tier, location, PERCENTILE_APPROX(budget, ARRAY(0.25, 0.5, 0.75)) AS budget_quartiles, ROUND(AVG(budget), 2) AS avg_budget, SORT_ARRAY(COLLECT_SET(dept_name)) AS dept_name_list FROM base GROUP BY CASE WHEN budget >= 3588000 THEN 'HIGH' ELSE 'LOW' END, location ORDER BY budget_tier DESC;
